#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { execSync } from 'child_process';

const ROOT = path.resolve(process.cwd());
const PATCH_FILE_PATH = path.join(ROOT, '.opencode', 'ace-patch-card.json');

/**
 * Reads the full ACE context JSON generated by the original script.
 * @returns {object} The parsed context object.
 */
function readAceContext() {
    const contextPath = path.join(ROOT, 'ace-context.json');
    try {
        const content = fs.readFileSync(contextPath, 'utf8');
        return JSON.parse(content);
    } catch (e) {
        console.error("Failed to read or parse ace-context.json. Ensure the main context script ran first.", e.message);
        return null;
    }
}

/**
 * Generates the structured patch card based on the context.
 * @param {object} context The full context object from ace-context.json.
 * @returns {object} The structured patch card object.
 */
function generatePatchCard(context) {
    if (!context) {
        return { error: "Context object not found. Run the main context script first." };
    }

    // Logic to condense the full context into a patch card structure
    const patchCard = {
        sourceRef: "docs/opencode/ace-context.md",
        taskId: "generate_patch_card",
        summary: "Generates a compact, actionable patch card from the full ACE context map.",
        current_behavior: [
            "Reads full context from .opencode/ace-context.json",
            "Analyzes envVars, ownerFiles, and scripts."
        ],
        desired_change: [
            "Output only a machine-readable patch card JSON",
            "Focus on actionable insights (e.g., missing links, high-risk env vars)",
            "Maintain sourceRefs for verification"
        ],
        constraints: [
            "Do not include secrets in the final output.",
            "Keep the JSON structure concise (card format)."
        ],
        acceptance: [
            "patch-card.json exists in .opencode/",
            "Patch card reflects key missing pieces"
        ]
    };
    
    // Add specific fields based on the context structure
    patchCard.context_details = {
        envVars_count: context.envVars.length,
        ownerFiles_count: context.ownerFiles.length,
        scripts_count: Object.keys(context.packageScripts).length,
        dynamicHealth: context.dynamicHealth
    };

    return patchCard;
}

function main(){
    const context = readAceContext();
    const patchCard = generatePatchCard(context);
    
    const outDir = path.join(process.cwd(), '.opencode');
    try{ fs.mkdirSync(outDir, { recursive: true }); } catch(e){}
    const outPath = path.join(outDir, 'ace-patch-card.json');
    
    fs.writeFileSync(outPath, JSON.stringify(patchCard, null, 2));
    console.log(`\nSuccessfully wrote compact patch card to: ${outPath}`);
    console.log(JSON.stringify(patchCard, null, 2));
}

main();